INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, vendor, product_type, status, archived_at, publish_at, reorder_point, reorder_quantity, lead_time_days, safety_stock, supplier_id, country_of_origin, completeness_score, field_locks) VALUES ('bae9b870-ab7e-4b35-8fc0-3312b2ff4b12', '650e8400-e29b-41d4-a716-446655440001', NULL, 'BCA-AUD-1002', 'Pulse True Wireless Earbuds', 'pulse-earbuds-case', 'Compact earbuds with active noise cancellation and a case that charges wirelessly.', 'Pulse earbuds seal well enough to cancel a plane cabin without turning up the volume to compensate. Each bud is rated IPX4, so a sweaty run or a walk in the rain won''t end the relationship.
